from ansible.utils.unsafe_proxy import AnsibleUnsafeText, wrap_var


def test_wrap_var_wraps_set_members():
    original = {"alpha", "beta", 42}

    wrapped = wrap_var(original)

    assert isinstance(wrapped, set)
    assert wrapped is not original
    assert {str(item) for item in wrapped if isinstance(item, AnsibleUnsafeText)} == {
        "alpha",
        "beta",
    }
    assert 42 in wrapped
    assert len(wrapped) == len(original)
    assert original == {"alpha", "beta", 42}
